class SkipListNode {
    String userId;             // whose entry this is
    long score;                   // this player's current score
    SkipListNode[] forward;          // one forward pointer per level this node participates in

    SkipListNode(String userId, long score, int level) {
        this.userId = userId;               // store the player id
        this.score = score;                   // store the score
        this.forward = new SkipListNode[level]; // allocate forward pointers for this node's level
    }
}

// An ordered leaderboard structure supporting update and rank lookup in
// roughly logarithmic time, the same underlying idea Redis uses for its
// sorted sets.
class SkipListLeaderboard {
    private static final int MAX_LEVEL = 16;                                              // ceiling on how tall the skip list can grow
    private final SkipListNode head = new SkipListNode("", Long.MIN_VALUE, MAX_LEVEL);        // sentinel node before every real entry
    private final Map<String, Long> currentScoreByUser = new HashMap<>();                       // userId -> their latest known score
    private final Random random = new Random();                                                    // used only to pick each new node's level
    private int level = 1;                                                                            // how many levels are currently in use

