    // player's position always reflects only their latest score.
    public void updateScore(String userId, long newScore) {
        Long previousScore = currentScoreByUser.get(userId); // this player's prior score, if any
        if (previousScore != null) {
            remove(userId, previousScore); // remove the stale entry first
        }
        insert(userId, newScore);                    // insert at the position matching the new score
        currentScoreByUser.put(userId, newScore);       // remember this as their current score
    }

    // Returns this player's rank, where rank 1 is the highest score,
    // by counting how many nodes at the bottom level precede them.
    public int getRank(String userId) {
        Long score = currentScoreByUser.get(userId); // this player's current score
        if (score == null) return -1;                   // not on the leaderboard at all
        SkipListNode current = head;                        // start scanning from the sentinel
        int rank = 0;                                          // nodes counted so far
        for (int i = level-1; i >= 0; i--) {
            while (current.forward[i] != null && isHigherPriority(current.forward[i], score, userId)) {
                current = current.forward[i]; // advance past this higher-ranked node
                rank++;                          // count it
            }
        }
        return rank+1; // this player's own position is one past everyone who outranks them
    }

    private boolean isHigherPriority(SkipListNode node, long targetScore, String targetUserId) {
        // Higher score wins; a tie is broken by whichever user id sorts first,
        // giving a stable, deterministic order for equal scores.
        if (node.score != targetScore) return node.score > targetScore; // strictly higher score wins outright
        return node.userId.compareTo(targetUserId) < 0;                    // equal scores, alphabetically first user id wins
    }

    private void insert(String userId, long score) {
        SkipListNode[] update = new SkipListNode[MAX_LEVEL]; // last node before the insertion point, per level
        SkipListNode current = head;                            // start scanning from the sentinel
        for (int i = level-1; i >= 0; i--) {
            while (current.forward[i] != null && isHigherPriority(current.forward[i], score, userId)) {
                current = current.forward[i]; // keep advancing while the next node outranks the new entry
            }
            update[i] = current; // remember where this level's insertion point is
        }
        int newLevel = randomLevel();     // how tall this new node will be
        if (newLevel > level) {              // the skip list needs to grow taller
            for (int i = level; i < newLevel; i++) update[i] = head; // new top levels start right after the sentinel
            level = newLevel;                                          // record the new overall height
        }
        SkipListNode newNode = new SkipListNode(userId, score, newLevel); // the node being inserted
        for (int i = 0; i < newLevel; i++) {
            newNode.forward[i] = update[i].forward[i]; // splice in after each level's insertion point
            update[i].forward[i] = newNode;
        }
    }

    private void remove(String userId, long score) {
        SkipListNode[] update = new SkipListNode[MAX_LEVEL]; // last node before the target, per level
        SkipListNode current = head;                            // start scanning from the sentinel
        for (int i = level-1; i >= 0; i--) {
            while (current.forward[i] != null && !(current.forward[i].userId.equals(userId) && current.forward[i].score == score)
                    && isHigherPriority(current.forward[i], score, userId)) {
                current = current.forward[i]; // keep advancing until just before the target node
            }
            update[i] = current; // remember where this level's removal point is
        }
        SkipListNode target = update[0].forward[0]; // the node that should be the one to remove
        if (target != null && target.userId.equals(userId)) {
            for (int i = 0; i < level; i++) {
                if (update[i].forward[i] != target) break; // this level doesn't reference the target, stop
                update[i].forward[i] = target.forward[i];     // unlink the target at this level
            }
        }
    }

    private int randomLevel() {
        int newLevel = 1;                                                    // every node exists at least at level 1
        while (random.nextDouble() < 0.5 && newLevel < MAX_LEVEL) newLevel++;    // coin flip decides whether to grow taller
        return newLevel; // this new node's height
