    // player's position always reflects only their latest score.
    void updateScore(const std::string& userId, long long newScore) {
        auto it = currentScoreByUser_.find(userId);   // this player's prior score, if any
        if (it != currentScoreByUser_.end()) {
            remove(userId, it->second);   // remove the stale entry first
        }
        insert(userId, newScore);                    // insert at the position matching the new score
        currentScoreByUser_[userId] = newScore;         // remember this as their current score
