    std::map<std::string, long long> currentScoreByUser_;     // userId -> their latest known score
    std::mt19937 rng_;                                            // used only to pick each new node's level
    std::uniform_real_distribution<double> dist_;
    int level_ = 1;                                                  // how many levels are currently in use
