        leaderboard.updateScore("Carol", 95);       // Carol joins with 95

        System.out.println("Alice's rank: " + leaderboard.getRank("Alice")); // expect 1, highest score
        System.out.println("Carol's rank: " + leaderboard.getRank("Carol")); // expect 2
        System.out.println("Bob's rank: " + leaderboard.getRank("Bob"));       // expect 3, lowest score

        leaderboard.updateScore("Bob", 105); // Bob has a great match and takes the lead
        System.out.println("After Bob's update to 105:");
        System.out.println("Bob's rank: " + leaderboard.getRank("Bob"));       // expect 1, now the highest
        System.out.println("Alice's rank: " + leaderboard.getRank("Alice")); // expect 2, pushed down one
        System.out.println("Carol's rank: " + leaderboard.getRank("Carol")); // expect 3, pushed down one

        leaderboard.updateScore("Dave", 95); // Dave ties Carol's score of 95 exactly
        System.out.println("After Dave ties Carol's score of 95:");
        System.out.println("Carol's rank: " + leaderboard.getRank("Carol")); // expect 3, alphabetically before Dave
        System.out.println("Dave's rank: " + leaderboard.getRank("Dave"));       // expect 4, tie broken alphabetically
        System.out.println("Tie correctly broken with Carol ahead of Dave: " + (leaderboard.getRank("Carol") < leaderboard.getRank("Dave")));
    }
